const VER=(document.currentScript&&document.currentScript.src.split('?v=')[1])||'',ensureUniv=()=>window.JukenUniv?Promise.resolve():new Promise(res=>{const sc=document.createElement('script');sc.src='masters-univ.js?v='+VER;sc.onload=res;sc.onerror=res;document.head.appendChild(sc)});
const C=StudyCore,$=id=>document.getElementById(id),q=new URLSearchParams(location.search),family=q.get('demo')==='family',demo=q.get('demo')==='1'||family;
const role=q.get('role')==='teacher'?'teacher':'student';
const S={role,actor:null,students:[],studentId:null,page:role==='teacher'?'students':(['today','plan'].includes(q.get('page'))?q.get('page'):'today'),date:jstToday(),busy:false,error:'',wizard:null,planId:null,teacherSettings:C.empty().teacherSettings,savedAt:null,ready:false,pdf:null,pdfHandoffApplied:false};
function jstToday(){return new Intl.DateTimeFormat('sv-SE',{timeZone:'Asia/Tokyo',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date())}
function esc(v){return String(v==null?'':v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function btn(label,action,cls='action',data={}){return '<button type="button" class="'+cls+'" data-action="'+action+'" '+Object.entries(data).map(([k,v])=>'data-'+k+'="'+esc(v)+'"').join(' ')+'>'+esc(label)+'</button>'}
function field(label,name,value='',type='text',extra=''){return '<label class="field">'+esc(label)+'<input name="'+name+'" type="'+type+'" value="'+esc(value)+'" '+extra+'></label>'}
function select(label,name,values,value){return '<label class="field">'+esc(label)+'<select name="'+name+'">'+values.map(v=>{const a=Array.isArray(v)?v:[v,v];return '<option value="'+esc(a[0])+'" '+(String(a[0])===String(value)?'selected':'')+'>'+esc(a[1])+'</option>'}).join('')+'</select></label>'}
function card(title,html){return '<section class="card"><h3>'+esc(title)+'</h3>'+html+'</section>'}
function hint(s){return '<p class="formhint">'+esc(s)+'</p>'}
function item(){return S.students.find(s=>s.studentId===S.studentId)||null}
function doc(){return item()?.doc||C.empty()}
function plan(){return doc().plans.find(p=>p.id===(S.planId||doc().activeId))||C.active(doc())||doc().plans[doc().plans.length-1]||null}
function taskPlan(id){return doc().plans.find(p=>p.tasks.some(t=>t.id===id))||plan()}
function tplan(){return taskPlan(S.taskId)}
function profileOf(){return doc().profile||C.defaultProfile()}
function modeLabel(r,t){const h=t&&t.unit==='分';return !r?'未記録':r.mode==='done'?(h?'できた':'完了'):r.mode==='none'?(h?'やらなかった':'取り組まなかった'):h?r.position+'分':'途中まで · '+r.position+'まで'}
function stBadge(r,t){if(!r)return t&&t.date<=S.date?'<span class="stbadge pending">未記録</span>':'';return r?'<span class="stbadge '+r.mode+'">'+(r.mode==='done'?'できた':r.mode==='none'?'やらなかった':t&&t.unit==='分'?r.position+'分':'途中まで')+'</span>':''}
function pct(p,d){if(!p||!p.tasks.length)return 0;return Math.round(p.tasks.filter(t=>d.records[t.id]?.mode==='done').length/p.tasks.length*100)}
function progress(n){return '<div class="bar" role="progressbar" aria-label="完了した取り組むことの割合" aria-valuenow="'+n+'" aria-valuemin="0" aria-valuemax="100"><span style="width:'+n+'%"></span></div>'}
