const H_SUBJ=['英語','数学','国語','理科','社会','その他'],DAYS_JA=['月','火','水','木','金','土','日'],MENU_OPT=['英語','数学','国語','理科・社会','学校の宿題','休み'];
function saveDraft(){if(S.wizard&&!S.wizard.rebuildId)localStorage.setItem(draftKey(),JSON.stringify(S.wizard))}
function newDraft(){return {step:0,input:{type:'test',title:'',target:'',start:S.date,goal:C.add(S.date,14),materials:[{name:'',subject:'数学',from:1,to:20,unit:'ページ',minutes:10}],availability:profileOf().availability.slice(),hwWeekly:profileOf().hwWeekly||'ほとんどない',reserveDay:profileOf().reserveDay||'',busyNote:'',busyDates:JSON.parse(JSON.stringify(profileOf().busyDates||[])),habit:{goalDays:5,goalMin:30,lastWeekDays:'1〜2日',menu:['英語','数学','英語','数学','国語','休み','休み'],cMaterials:''},homeworks:[{name:'',subject:'数学',unit:'ページ',amount:10,due:'',unitMin:''}]},rebuildId:null}}
async function api(source,params={}){
 if(demo)return demoApi(source,params);
 const payload={source,role:S.role,...params,idToken:liff.getIDToken(),accessToken:liff.getAccessToken()};
 const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),30000);let r,j;
 try{r=await fetch(CONFIG.api,{method:'POST',headers:{'Content-Type':'text/plain;charset=utf-8'},body:JSON.stringify(payload),signal:controller.signal});if(!r.ok)throw Error('接続エラーです。時間をおいて再試行してください');const text=await r.text();try{j=JSON.parse(text)}catch{throw Error('保存APIが未更新か接続に失敗しました。管理者に確認してください')}}finally{clearTimeout(timer)}
 if(!j.ok){if(j.code==='CONFLICT'&&j.item)replaceItem(j.item);throw Error(j.code?.startsWith('AUTH_')?'LINEの認証が切れました。画面を開き直してください':j.error||'保存できませんでした')}return j;
}
function demoApi(source,p){
 // ?demo=1：1人のデモ。?demo=family：保護者（母）のLINEに、2人の生徒（兄弟）が付いているデモ。どちらもこのブラウザの中だけに保存する
 const ids=family?['S2','S3']:['DEMO'],keyOf=id=>'manabi-functional-demo-v1'+(family?':'+id:'');
 const load=id=>{const st=JSON.parse(localStorage.getItem(keyOf(id))||'null')||{studentId:id,name:family?id:'テスト生徒',revision:0,doc:C.empty()};if(family)st.relation='母';st.doc=C.resume(st.doc,S.date);return st};
 if(source==='app_boot')return {ok:true,actor:{id:'DEMO',name:'テスト利用',role:S.role},students:ids.map(load),teacherSettings:JSON.parse(localStorage.getItem('manabi-functional-demo-v1teacher')||'null')||C.empty().teacherSettings,today:jstToday()};
 if(source==='app_teacher_settings'){localStorage.setItem('manabi-functional-demo-v1teacher',JSON.stringify(p.settings));return {ok:true,settings:p.settings}}
 if(source==='app_action'){const store=load(p.studentId||ids[0]);if(p.revision!==store.revision){replaceItem(store);throw Error('別の画面で更新されています。もう一度操作してください')}store.doc=C.apply(store.doc,p.action,{name:'テスト講師',role:S.role,relation:store.relation||''},{id:crypto.randomUUID(),today:S.date,now:new Date().toISOString()});store.revision++;localStorage.setItem(keyOf(store.studentId),JSON.stringify(store));return {ok:true,item:store}}
 throw Error('デモでは利用できない操作です')}
function replaceItem(it){const i=S.students.findIndex(s=>s.studentId===it.studentId);if(i<0)S.students.push(it);else S.students[i]=it}
async function busy(job,msg='保存しました'){if(S.busy)return;S.busy=true;S.error='';renderStatus();const key=formDraftKey(),buttons=Array.from(document.querySelectorAll('button:not(#modal button)')).map(b=>[b,b.disabled]);buttons.forEach(([b])=>b.disabled=true);let okay=false;try{await job();okay=true}catch(e){S.error=e.name==='AbortError'?'応答を確認できませんでした。入力は残っています。「最新のデータを読み込む」で保存されたか確認してください':e.message}finally{S.busy=false;if(S.error){buttons.forEach(([b,disabled])=>b.disabled=disabled);renderStatus();window.scrollTo(0,0)}else{try{sessionStorage.removeItem(key)}catch{}render()}}if(okay&&msg)showToast(msg)}
function showToast(m){const t=$('toast');t.textContent=m;t.hidden=false;clearTimeout(showToast.t);showToast.t=setTimeout(()=>{t.hidden=true},2400)}
// 入力した内容が画面の再表示で消えないようにこの端末の中に一時的に残す（保存できたら消す）
function formDraftKey(){return 'manabi-form:'+S.role+':'+(S.studentId||'')+':'+S.page}
function saveFormDraft(e){const t=e.target;if(!t||!t.name||S.page==='wizard'||t.type==='password')return;try{const k=formDraftKey(),o=JSON.parse(sessionStorage.getItem(k)||'{}');o[t.name]=t.type==='checkbox'?t.checked:t.value;sessionStorage.setItem(k,JSON.stringify(o))}catch{}}
function restoreFormDraft(){if(S.page==='wizard')return;try{const o=JSON.parse(sessionStorage.getItem(formDraftKey())||'{}');Object.entries(o).forEach(([n,v])=>{const el=$('content').querySelector('[name="'+n+'"]');if(!el||el.disabled||el.type==='hidden')return;if(el.type==='checkbox')el.checked=!!v;else el.value=v})}catch{}}
async function boot(){const result=await api('app_boot');S.actor=result.actor;S.students=result.students;S.date=result.today;S.selectedDate=S.selectedDate||S.date;S.teacherSettings=result.teacherSettings||S.teacherSettings;if(!S.students.some(s=>s.studentId===S.studentId))S.studentId=S.students[0]?.studentId;if(!S.pdfHandoffApplied&&q.get('view')==='pdf'){const requested=q.get('plan');if(requested){const owner=S.students.find(it=>it.doc.plans.some(p=>p.id===requested));if(!owner)throw Error('この計画が見つかりません。作成したLINEアカウントで開いてください');S.studentId=owner.studentId;S.planId=requested}S.page='pdf';S.pdfHandoffApplied=true}S.ready=true;S.savedAt=new Date().toLocaleTimeString('ja-JP',{hour:'2-digit',minute:'2-digit'});render()}
async function mutate(action){const current=item();if(!current)throw Error('生徒を選んでください');const requestId=crypto.randomUUID();const snapshot=current.doc;if(['report','study_time'].includes(action.type)){try{current.doc=C.apply(current.doc,action,{role:S.role,relation:current.relation||''},{id:requestId,today:S.date,now:new Date().toISOString()});render()}catch(e){current.doc=snapshot}}let result;try{result=await api('app_action',{studentId:current.studentId,revision:current.revision,requestId,action})}catch(e){current.doc=snapshot;render();throw e}replaceItem(result.item);S.savedAt=new Date().toLocaleTimeString('ja-JP',{hour:'2-digit',minute:'2-digit'})}
function modalOpen(o){return new Promise(res=>{const m=$('modal');$('modalTitle').textContent=o.title||'';$('modalMsg').innerHTML='<p>'+esc((o.body||'').split('\n').filter(Boolean).join(''))+'</p>';const ok=$('modalOk'),ng=$('modalCancel'),ex=$('modalExtra');ok.textContent=o.ok||'OK';ok.className=o.danger?'primary danger':'primary';ng.hidden=!o.cancel;ng.textContent=o.cancel||'';ex.hidden=!o.extra;ex.innerHTML=o.extra?btn(o.extra.label,o.extra.action,'secondary'):'';ok.disabled=false;ng.disabled=false;m.hidden=false;ok.focus();const done=v=>{m.hidden=true;ok.onclick=ng.onclick=null;m.onclick=null;res(v)};ok.onclick=()=>done(true);ng.onclick=()=>done(false);ex.onclick=e=>{if(e.target.closest('[data-action]'))done(false)}})}
const ask=(title,body,ok,cancel,danger)=>modalOpen({title,body,ok,cancel:cancel||'やめる',danger});
const notice=(title,body,extra)=>modalOpen({title,body,ok:'OK',extra});
const isRel=el=>!!el&&el.validity&&el.validity.rangeUnderflow&&((el.type==='date'&&el.name==='goal')||/^m\d+_to$/.test(el.name||''));
function fieldMsg(el){const v=el.validity;if(v.valueMissing)return el.tagName==='SELECT'?'選んでください':el.type==='date'?'日付を選んでください':'入力してください';if(v.rangeOverflow)return el.type==='date'?(el.max||'')+'以前の日付にしてください':el.max+'以下で入れてください';if(v.rangeUnderflow){if(el.type==='date'){const nm=el.name||'';return nm==='goal'?'「いつから」は「いつまで」と同じかそれより前の日付にしてください':nm==='start'?'今日以降の日付にしてください':'「'+el.min+'」以降の日付にしてください'}if(/^m\d+_to$/.test(el.name||''))return '「はじめ」は「おわり」と同じかそれより小さい数字にしてください';return el.min+'以上で入れてください'}if(v.stepMismatch||v.badInput)return '数字で入れてください';if(v.tooLong)return el.maxLength+'文字以内で入れてください';return el.validationMessage||'入力を確認してください'}
function placeArrow(b,el){try{const bb=b.getBoundingClientRect(),eb=el.getBoundingClientRect();if(bb.width&&isRel(el))b.style.setProperty('--ax',(bb.width/2-6)+'px');else if(bb.width)b.style.setProperty('--ax',Math.max(14,Math.min(bb.width-26,eb.left+Math.min(eb.width/2,40)-bb.left-6))+'px')}catch(x){}}
function clearBubble(){document.querySelectorAll('.fbubble').forEach(b=>b.remove())}
// 吹き出しの置き場と、頭につける欄の名前。行（曜日・科目の行）では、行の下に、全幅で出す
function bubbleBox(el){return el.closest('.inlinefields,.grid2')||el.closest('.dayrow,.subjrow')||el.closest('.field')||el.parentNode}
function bubbleLabel(el){const grid=el.closest('.inlinefields,.grid2');if(grid&&!isRel(el)&&el.closest('.field'))return [...el.closest('.field').childNodes].filter(x=>x.nodeType===3).map(x=>x.textContent).join('').trim();return el.closest('.subjrow')?(el.getAttribute('aria-label')||''):''}
function showFieldErrors(els){clearBubble();if(!els.length)return;els.forEach(el=>{const dt=el.closest('details');if(dt)dt.open=true});const first=els[0];
 try{first.scrollIntoView({behavior:'smooth',block:'center'})}catch(x){first.scrollIntoView()}
 setTimeout(()=>{try{first.focus({preventScroll:true})}catch(x){}els.forEach(el=>{const box=bubbleBox(el),b=document.createElement('div');b.className='fbubble';b.setAttribute('role','alert');const lb=bubbleLabel(el);b.textContent=(lb?lb+'：':'')+fieldMsg(el);box.appendChild(b);placeArrow(b,el);const off=()=>{b.remove();el.removeEventListener('input',off);el.removeEventListener('change',off)};el.addEventListener('input',off);el.addEventListener('change',off);b.addEventListener('click',off)})},380)}
const showFieldError=el=>showFieldErrors([el]);
function liveBubble(el){if(!el||!el.parentNode)return;const box=bubbleBox(el);if(el._bub&&el._bub.parentNode)el._bub.remove();const b=document.createElement('div');b.className='fbubble';b.setAttribute('role','alert');const lb=bubbleLabel(el);b.textContent=(lb?lb+'：':'')+fieldMsg(el);box.appendChild(b);placeArrow(b,el);el._bub=b;const off=()=>{b.remove();el.removeEventListener('input',chk);el.removeEventListener('change',chk)},chk=()=>{if(el.validity.valid)off()};el.addEventListener('input',chk);el.addEventListener('change',chk);b.addEventListener('click',off)}
function syncRel(t){const f=t.form;if(!f)return[];const q=n=>f.querySelector('[name='+n+']'),out=[];if(t.name==='start'){const g=q('goal');if(g){g.min=t.value||g.min;out.push(g)}}const m=/^m(\d+)_from$/.exec(t.name||'');if(m){const to=q('m'+m[1]+'_to');if(to){to.min=String(Math.max(1,Number(t.value)||1));out.push(to)}}return out}
document.addEventListener('input',e=>{const t=e.target;if(!t||t.tagName!=='INPUT')return;const rel=syncRel(t);rel.forEach(r=>{if(r.value!==''&&!r.validity.valid)liveBubble(r);else if(r._bub)r._bub.remove()});if(t.type==='number'&&t.value!==''&&!t.validity.valid&&!t.closest('.hmrow')&&!rel.length&&(/^m\d+_to$/.test(t.name||'')))liveBubble(t)},true);
document.addEventListener('change',e=>{const t=e.target;if(!t||t.tagName!=='INPUT')return;if(t.type==='date'||t.type==='number'){syncRel(t).forEach(r=>{if(r.value!==''&&!r.validity.valid)liveBubble(r);else if(r._bub)r._bub.remove()});if(t.value!==''&&!t.validity.valid&&!t.closest('.hmrow'))liveBubble(t)}},true);

document.addEventListener('keydown',e=>{const t=e.target;if(!t||t.tagName!=='INPUT'||t.type!=='number')return;const k=e.key,mn=t.getAttribute('min'),st=t.getAttribute('step');if(k==='e'||k==='E'||k==='+'||(k==='-'&&mn!==null&&Number(mn)>=0)||(k==='.'&&(st===null||Number.isInteger(Number(st)))))e.preventDefault()});
document.addEventListener('input',e=>{const t=e.target;if(!t||t.tagName!=='INPUT'||t.type!=='number'||t.value==='')return;let n=Number(t.value);if(Number.isNaN(n))return;const mx=t.getAttribute('max'),mn=t.getAttribute('min');if(mn!==null&&Number(mn)>=0&&n<0)n=0;if(mx!==null&&n>Number(mx))n=Number(mx);if(String(n)!==t.value&&(n!==Number(t.value)))t.value=n;const row=t.closest('.hmrow');if(row){const h=row.querySelector('input[name$="_h"]'),m=row.querySelector('input[name$="_m"]');if(h&&m&&h.value!==''&&m.value!==''&&Number(h.value)*60+Number(m.value)>720){m.value=Math.max(0,720-Number(h.value)*60)}hmCheck(row.parentNode)}},true);
document.addEventListener('change',e=>{const t=e.target;if(!t||t.tagName!=='INPUT'||t.type!=='number'||t.value==='')return;const mn=t.getAttribute('min');if(mn!==null&&Number(t.value)<Number(mn))t.value=mn});
const caretEnd=e=>{const t=e.target;if(!t||t.tagName!=='INPUT'||t.type!=='number')return;setTimeout(()=>{if(document.activeElement!==t)return;const v=t.value;t.value='';t.value=v},0)};  // 数字の欄だけ。最初に触れたときだけ、右端へ（文字の欄は、触った位置のまま）
document.addEventListener('focusin',caretEnd);
function renderStatus(){$('busy').hidden=!S.busy;$('error').hidden=!S.error;$('error').textContent=S.error||'';if(S.error&&S.error!==S.shownError){S.shownError=S.error;notice('確認してください',S.error,{label:'最新のデータを読み込む',action:'refresh'})}if(!S.error)S.shownError='';const st=$('status'),msg=demo?'動作デモ：入力はこのブラウザの中にだけ保存されます':'';st.hidden=!msg;st.textContent=msg}
function toTop(){const c=$('content');if(c)c.scrollTop=0;window.scrollTo(0,0);document.documentElement.scrollTop=0;document.body.scrollTop=0}
// 入力すると候補が出る欄（大学名・教材名）。候補は、入力した文字を含むものすべて。選ぶと、隠した欄に値が入り、変更が伝わる
const COMBO={};
const nz=x=>String(x||'').toLowerCase().replace(/[\s　]/g,'').replace(/[Ａ-Ｚａ-ｚ０-９]/g,c=>String.fromCharCode(c.charCodeAt(0)-0xFEE0));
function combo(label,name,items,value,ph,free){COMBO[name]=items;const cur=items.find(x=>x.v===value);return '<div class="combo" data-combo="'+name+'"'+(free?' data-free="1"':'')+'><div class="field"><span>'+esc(label)+'</span><input type="text" data-comboq="'+name+'" autocomplete="off" autocorrect="off" spellcheck="false" placeholder="'+esc(ph||'')+'" value="'+esc(cur?cur.t:'')+'"></div><input type="hidden" name="'+name+'" value="'+esc(value||'')+'"><div class="combolist" hidden></div></div>'}
function comboShow(box,q){const items=COMBO[box.dataset.combo]||[],n=nz(q),hits=(n?items.filter(x=>x.k.includes(n)):items).slice(0,40),L=box.querySelector('.combolist');let h=hits.map(x=>'<button type="button" data-pick="'+esc(x.v)+'"><span>'+esc(x.t)+'</span><small>'+esc(x.s||'')+'</small></button>').join('');if(box.dataset.free&&q.trim()&&!items.some(x=>x.t===q.trim()))h+='<button type="button" data-pick="__free:'+esc(q.trim())+'"><span>「'+esc(q.trim())+'」をその他（手入力）で追加</span></button>';L.innerHTML=h||'<p class="caption pad">見つかりません</p>';L.hidden=false}
document.addEventListener('input',e=>{const t=e.target;if(!t.dataset||!t.dataset.comboq)return;const box=t.closest('.combo');box.querySelector('input[type=hidden]').value='';comboShow(box,t.value)});
