function partialLabel(t){return t.unit==='分'?'何分やった？':t.unit==='ページ'?'どのページまで？':'何番まで？'}
function rowBtn(title,desc,page){return '<button type="button" class="action" data-action="page" data-page="'+page+'"><span><b>'+esc(title)+'</b></span></button>'}
function noPlan(){return '<div class="iconrow" role="group" aria-label="共通のメニュー">'+iconBtn(ICON_GEAR,'リマインドの設定','data-action="page" data-page="'+(S.role==='teacher'?'teacherSettings':'settings')+'"')+'</div><h1 class="page-title">計画を作りましょう</h1><div class="hero"><p>毎日取り組むことを一緒に組み立てます。約3分で作れます。</p>'+btn('計画を作る','new','primary')+'</div>'}
function taskCard(t,d,interactive=true){const r=d.records[t.id],amount=t.text.startsWith(t.name)?t.text.slice(t.name.length).trim():t.text;return '<button type="button" class="task '+(r?.mode||'')+'" data-action="editTask" data-id="'+esc(t.id)+'" style="text-align:left"><span class="box2" aria-hidden="true">'+(r?.mode==='done'?'✓':r?.mode==='partial'?'◐':'')+'</span><span class="task-title"><span class="t1">'+esc(t.date.slice(5).replace('-','/'))+' ・ '+esc(t.subject)+'</span><span class="t2">'+esc(t.name)+'</span><span class="t3">'+esc(amount)+' ・ '+t.minutes+'分</span></span></button>'}
function taskRow(t,d,ro){const r=d.records[t.id],open=S.openTask===t.id&&!ro,future=!!ro||t.date>S.date,stLabel=r?(r.mode==='done'?'できた':r.mode==='none'?'やらなかった':t.unit==='分'?r.position+'分':'途中まで'):(t.date>S.date?'':'未記録'),amount=t.text.startsWith(t.name)?t.text.slice(t.name.length).trim():t.text,hab=t.unit==='分',pl=r&&r.position!=null&&(r.mode==='partial'||(r.mode==='done'&&(hab?r.position>t.minutes:t.to!=null&&r.position>t.to)))?posLabel(t,r.position):'',plTxt=pl&&!(hab&&r.mode==='partial')?(hab?pl+'やった':pl.endsWith('まで')?pl:pl+'まで'):'';
 const manual=t.from==null&&taskPlan(t.id).type!=='habit',carry=m=>S.carryMode===m&&manual?'<div class="carrybox"><p class="q2">残りはどうしますか？</p><div class="two">'+btn('明日にやる','carryYes','secondary')+btn('やらない','carryNo','secondary')+'</div></div>':'';
 const partialForm=S.partialOpen&&!manual?'<form data-form="partial">'+field(partialLabel(t),'position',r?.position??'','number','required inputmode="numeric" placeholder="例：'+(hab?Math.max(1,Math.round(t.minutes/2)):Math.round(((t.from??1)+(t.to??10))/2))+'" min="'+(hab?1:(t.from??0))+'" max="'+(hab?360:(t.to??180))+'"')+'<button class="primary">記録する</button></form>':'';
 const matEnd=t.to==null?null:Math.max(t.to,((taskPlan(t.id).input.materials||[]).find(m=>m.name===t.name)||{to:t.to}).to),canExtra=!hab&&!manual&&matEnd!=null&&matEnd>t.to,extraForm=S.extraOpen&&canExtra?'<form data-form="extra">'+field(partialLabel(t),'position',hab?(r&&r.mode==='done'&&r.position>t.minutes?r.position:''):(r&&r.mode==='done'&&r.position>t.to?r.position:''),'number','required inputmode="numeric" placeholder="例：'+(hab?t.minutes+15:Math.min(matEnd,t.to+3))+'" min="'+(hab?t.minutes+1:t.to+1)+'" max="'+(hab?360:matEnd)+'"')+'<button class="primary">記録する</button></form>':'';
 const habitPanel='<div class="choices"><form data-form="partial">'+hmField('どれだけやった？','position',r&&r.position!=null?r.position:t.minutes,1,360)+'<button class="primary">記録する</button></form>'+btn('やらなかった','reportNone','secondary')+'</div>';
 const panel=open?'<div class="taskpanel">'+(future?'<p class="q">この日はまだ記録できません</p>':hab?habitPanel:'<div class="choices">'+btn(t.unit==='分'?'できた':'全部できた','reportDone','secondary')+(canExtra?'<div class="joined">'+btn('予定より多くやった','showExtra','secondary'+(S.extraOpen?' on':''))+extraForm+'</div>':'')+(manual?'<div class="joined">'+btn('途中まで','carryAsk','secondary'+(S.carryMode==='partial'?' on':''),{mode:'partial'})+carry('partial')+'</div><div class="joined">'+btn('やらなかった','carryAsk','secondary'+(S.carryMode==='none'?' on':''),{mode:'none'})+carry('none')+'</div>':'<div class="joined">'+btn(t.unit==='分'?'やった時間を入れる':'途中まで','showPartial','secondary'+(S.partialOpen?' on':''))+partialForm+'</div>'+btn('やらなかった','reportNone','secondary'))+'</div>')+'</div>':'';
 return '<div class="taskwrap"><div class="task '+(r?.mode||'')+'"><span class="task-title"><span class="trow"><span class="t1">'+(t._pt?esc(t._pt)+' ・ ':'')+esc(t.unit==='分'?'習慣':t.subject)+'</span>'+(stLabel?'<span class="stbadge '+(r?r.mode:'pending')+'">'+stLabel+'</span>':'')+'</span><span class="t2">'+esc(t.name)+'</span><span class="t3">'+(t.unit==='分'?'':esc(amount)+' ・ ')+t.minutes+'分'+(plTxt?' ・ '+esc(plTxt):'')+'</span></span>'+(future?'':'<div class="taskact taskset"><button type="button" class="tact'+(open?' on':'')+'" data-action="openTask" data-id="'+esc(t.id)+'" aria-expanded="'+open+'">'+(open?'閉じる ▴':(r?'修正する':'記録する')+' ▾')+'</button>'+panel+'</div>')+'</div></div>'}
function noActive(d){return '<h1 class="page-title">今日取り組むこと</h1><div class="notice">進行中の計画はありません。止めている計画の再開は「計画」タブの右上「設定」の「各計画の停止・再開」からできます。</div>'+d.plans.map(q=>card(q.title,q.status==='paused'?'<p class="caption">一時停止中</p>':'<p class="caption">終わりました</p>')).join('')}
function todayView(){const d=doc(),aps=C.activePlans(d);if(!aps.length)return d.plans.length?noActive(d):noPlan();
 const date=S.selectedDate||S.date,isToday=date===S.date,tasks=[],monday=C.week(date),future=date>S.date,tm=d.records['time:'+date]?.minutes,multi=aps.length>1;
 aps.forEach(p=>p.tasks.filter(t=>t.date===date).sort((a,b)=>a.id<b.id?-1:a.id>b.id?1:0).forEach(t=>tasks.push(multi?Object.assign({},t,{_pt:p.title}):t)));
 const done=tasks.filter(t=>d.records[t.id]).length;
 let h='<h1 class="page-title">'+(isToday?'今日取り組むこと':esc(mdw(date))+'に取り組むこと')+'</h1><p class="subtle">'+aps.map(p=>esc(p.title)).join('／')+'</p>';
 aps.forEach(p=>{const st=C.stateOf(p,S.date),pr=C.progressOf(d,p,S.date),pre=multi?'<b>'+esc(p.title)+'</b>：':'';
  if(st.phase==='after')h+='<div class="notice">'+pre+'この計画は終わりました。</div>'+btn('新しい計画を追加する','new','primary');
  else if(st.phase==='before')h+='<div class="notice">'+pre+esc(mdw(p.start))+'から始まります。</div>';
  if(pr&&pr.needsReplan&&st.phase==='during')h+='<div class="alert">'+pre+'<b>遅れがあります</b>（'+pr.missedCount+'個）'+(pr.fits?'':' このままだと期間内に終わりません。')+'</div>'+btn('遅れを組み直す','replan','primary',{id:p.id})});
 const st0=S.stripStart||C.add(S.date,-1),m0=C.add(st0,0),m1=C.add(st0,6),ym=x=>Number(x.slice(0,4))+'年'+Number(x.slice(5,7))+'月';h+='<p class="stripmonth">'+(m0.slice(0,7)===m1.slice(0,7)?ym(m0):ym(m0)+'〜'+(m0.slice(0,4)===m1.slice(0,4)?Number(m1.slice(5,7))+'月':ym(m1)))+'</p><div class="strip" role="group" aria-label="日付を選ぶ">'+Array.from({length:7},(_,i)=>{const dt=C.add(st0,i),wd='日月火水木金土'[new Date(dt+'T00:00:00Z').getUTCDay()];return '<button type="button" data-action="date" data-date="'+dt+'" class="'+(dt===date?'sel':'')+'" '+(dt===S.date?'aria-current="date"':'')+'>'+wd+'<b>'+Number(dt.slice(8))+'</b><small>'+(dt===S.date?'今日':'')+'</small></button>'}).join('')+'</div>'+(S.stripStart?'<div class="stripnav">'+btn('‹ 前の7日','strip','linkbtn',{dir:-1})+btn('次の7日 ›','strip','linkbtn',{dir:1})+btn('今日に戻る','stripToday','linkbtn')+'</div>':'<div class="stripnav">'+btn('‹ 前の7日','strip','linkbtn',{dir:-1})+btn('次の7日 ›','strip','linkbtn',{dir:1})+'</div>');
 if(!tasks.length)h+='<div class="empty">この日に取り組むことはありません。</div>';
 else h+='<p class="progress-label"><span><b>'+done+' / '+tasks.length+'</b> 完了</span></p>'+tasks.map(t=>taskRow(t,d)).join('');
 if(d.feedback.length)h+=card('講師からのひとこと','<p>'+esc(d.feedback[0].text)+'</p><p class="caption">'+esc(d.feedback[0].at.slice(0,10))+'</p>');
 return h}
function hmField(label,name,v,min,max){v=Number(v)||0;const lb=esc(label);return '<div class="field hmf"><span>'+lb+'</span><div class="hmrow" data-min="'+(min||0)+'" data-max="'+(max||720)+'"><input name="'+name+'_h" type="number" min="0" max="12" step="1" inputmode="numeric" required value="'+Math.floor(v/60)+'" aria-label="'+lb+'の時間"><b>時間</b><input name="'+name+'_m" type="number" min="0" max="59" step="1" inputmode="numeric" required value="'+(v%60)+'" aria-label="'+lb+'の分"><b>分</b></div></div>'}
function hmText(n){const h=Math.floor(n/60),m=n%60;return (h?h+'時間':'')+(m||!h?m+'分':'')}
function hmCheck(root){(root||document).querySelectorAll('.hmrow[data-min]').forEach(r=>{const h=r.querySelector('input[name$="_h"]'),m=r.querySelector('input[name$="_m"]');if(!h||!m)return;const mn=Number(r.dataset.min),mx=Number(r.dataset.max);let msg='';if(h.value!==''&&m.value!==''){const t=Number(h.value)*60+Number(m.value);if(mn>0&&t<mn)msg=hmText(mn)+'以上で入れてください';else if(t>mx)msg=hmText(mx)+'以内で入れてください'}m.setCustomValidity(msg)})}
